113	    pub fn resolve(&self, did: &str) -> Result<Document, ResolveError> {
114	        let method = did
115	            .strip_prefix("did:")
116	            .and_then(|rest| rest.split_once(':'))
117	            .map(|(method, _)| method)
118	            .ok_or_else(|| ResolveError::InvalidDid(did.to_string()))?;
119	        match method {
120	            "key" => resolve_key(did),
121	            "peer" => resolve_peer(did),
122	            "web" => self.resolve_web(did),
123	            other => Err(ResolveError::UnsupportedMethod(other.to_string())),
124	        }
125	    }
