127	    fn resolve_web(&self, did: &str) -> Result<Document, ResolveError> {
128	        let url = did_web_url(did)?;
129	        let body = self.transport.get(&url)?;
130	        let document: Document = serde_json::from_slice(&body)
131	            .map_err(|e| ResolveError::InvalidDocument { did: did.to_string(), reason: e.to_string() })?;
132	        if document.id.as_str() != did {
133	            return Err(ResolveError::DocumentMismatch { did: did.to_string(), found: document.id.to_string() });
134	        }
135	        Ok(document)
136	    }
137	}
