144	/// The HTTPS URL a `did:web` document is published at.
145	///
146	/// `did:web:example.com` → `https://example.com/.well-known/did.json`;
147	/// `did:web:example.com:a:b` → `https://example.com/a/b/did.json`; a port is
148	/// written percent-encoded in the host segment (`example.com%3A8443`).
149	pub fn did_web_url(did: &str) -> Result<String, ResolveError> {
150	    let invalid = || ResolveError::InvalidDid(did.to_string());
151	    let id = did.strip_prefix("did:web:").ok_or_else(invalid)?;
152	    let mut segments = id.split(':');
153	    let host = percent_decode(segments.next().unwrap_or_default()).ok_or_else(invalid)?;
154	    if host.is_empty() || host.contains('/') {
155	        return Err(invalid());
156	    }
157	    let path: Vec<String> = segments.map(percent_decode).collect::<Option<_>>().ok_or_else(invalid)?;
158	    if path.iter().any(|s| s.is_empty() || s.contains('/')) {
159	        return Err(invalid());
160	    }
161	    Ok(if path.is_empty() {
162	        format!("https://{host}/.well-known/did.json")
163	    } else {
164	        format!("https://{host}/{}/did.json", path.join("/"))
165	    })
166	}
167	
168	fn percent_decode(segment: &str) -> Option<String> {
169	    let bytes = segment.as_bytes();
170	    let mut out = Vec::with_capacity(bytes.len());
171	    let mut i = 0;
172	    while i < bytes.len() {
173	        if bytes[i] == b'%' {
174	            let hex = std::str::from_utf8(bytes.get(i + 1..i + 3)?).ok()?;
175	            out.push(u8::from_str_radix(hex, 16).ok()?);
176	            i += 3;
177	        } else {
178	            out.push(bytes[i]);
179	            i += 1;
180	        }
181	    }
182	    String::from_utf8(out).ok()
183	}
