190	fn resolve_peer(did: &str) -> Result<Document, ResolveError> {
191	    let id = did.strip_prefix("did:peer:").unwrap_or_default();
192	    if let Some(multibase) = id.strip_prefix('0') {
193	        single_key_document(did, multibase)
194	    } else if let Some(elements) = id.strip_prefix("2.") {
195	        peer_2_document(did, elements)
196	    } else {
197	        Err(ResolveError::InvalidDid(did.to_string()))
198	    }
199	}
