201	/// Checks that `multibase` is an Ed25519 multikey.
202	fn ed25519_multikey(did: &str, multibase: &str) -> Result<(), ResolveError> {
203	    match affinidi_encoding::decode_multikey_with_codec(multibase) {
204	        Ok((affinidi_encoding::ED25519_PUB, bytes)) if bytes.len() == 32 => Ok(()),
205	        _ => Err(ResolveError::InvalidDid(did.to_string())),
206	    }
207	}
