213	fn single_key_document(did: &str, multibase: &str) -> Result<Document, ResolveError> {
214	    ed25519_multikey(did, multibase)?;
215	    let vm_id = format!("{did}#{multibase}");
216	    to_document(did, json!({
217	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
218	        "id": did,
219	        "verificationMethod": [multikey(&vm_id, did, multibase)],
220	        "authentication": [vm_id],
221	        "assertionMethod": [vm_id],
222	        "capabilityInvocation": [vm_id],
223	        "capabilityDelegation": [vm_id],
224	    }))
225	}
226	
227	fn peer_2_document(did: &str, elements: &str) -> Result<Document, ResolveError> {
228	    let invalid = || ResolveError::InvalidDid(did.to_string());
229	    let mut methods = Vec::new();
230	    let mut relationships: Map<String, Value> = Map::new();
231	    let mut services = Vec::new();
232	
233	    for element in elements.split('.') {
234	        let mut chars = element.chars();
235	        let purpose = chars.next().ok_or_else(invalid)?;
236	        let body = chars.as_str();
237	        let relationship = match purpose {
238	            'A' => "assertionMethod",
239	            'V' => "authentication",
240	            'E' => "keyAgreement",
241	            'I' => "capabilityInvocation",
242	            'D' => "capabilityDelegation",
243	            'S' => {
244	                let raw = URL_SAFE_NO_PAD.decode(body.trim_end_matches('=')).map_err(|_| invalid())?;
245	                let abbreviated: Value = serde_json::from_slice(&raw).map_err(|_| invalid())?;
246	                let id = match services.len() {
247	                    0 => format!("{did}#service"),
248	                    n => format!("{did}#service-{n}"),
249	                };
250	                let mut service = expand_service(&abbreviated);
251	                service["id"] = json!(id);
252	                services.push(service);
253	                continue;
254	            }
255	            _ => return Err(invalid()),
256	        };
257	        if purpose != 'E' {
258	            ed25519_multikey(did, body)?;
259	        }
260	        let vm_id = format!("{did}#key-{}", methods.len() + 1);
261	        methods.push(multikey(&vm_id, did, body));
262	        relationships.entry(relationship).or_insert_with(|| json!([])).as_array_mut().unwrap().push(json!(vm_id));
263	    }
264	
265	    let mut document = json!({
266	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
267	        "id": did,
268	        "verificationMethod": methods,
269	        "service": services,
270	    });
271	    for (relationship, ids) in relationships {
272	        document[relationship] = ids;
273	    }
274	    to_document(did, document)
275	}
