277	/// Expands the abbreviated keys peer:2 uses for services (`t`, `s`, `r`, `a`, `dm`).
278	fn expand_service(value: &Value) -> Value {
279	    match value {
280	        Value::Object(map) => Value::Object(
281	            map.iter()
282	                .map(|(k, v)| {
283	                    let key = match k.as_str() {
284	                        "t" => "type",
285	                        "s" => "serviceEndpoint",
286	                        "r" => "routingKeys",
287	                        "a" => "accept",
288	                        other => other,
289	                    };
290	                    (key.to_string(), expand_service(v))
291	                })
292	                .collect(),
293	        ),
294	        Value::String(s) if s == "dm" => json!("DIDCommMessaging"),
295	        Value::Array(items) => Value::Array(items.iter().map(expand_service).collect()),
296	        other => other.clone(),
297	    }
298	}
