431	        let vc = vp.get("verifiableCredential").ok_or_else(|| malformed("verifiableCredential"))?;
432	        let credential = self.verify_credential(vc)?;
433	        if credential.subject != holder {
434	            return Err(VerifyError::HolderMismatch);
435	        }
436	
437	        let committed: HashSet<&str> = vc
438	            .pointer("/credentialSubject/_sd")
439	            .and_then(Value::as_array)
440	            .map(|digests| digests.iter().filter_map(Value::as_str).collect())
441	            .unwrap_or_default();
442	        let disclosures: Vec<Disclosure> = match vp.get("disclosures") {
443	            Some(list) => serde_json::from_value(list.clone()).map_err(|_| malformed("disclosures"))?,
444	            None => Vec::new(),
445	        };
446	        let mut claims = BTreeMap::new();
447	        for disclosure in disclosures {
448	            if !committed.contains(disclosure.digest().as_str()) {
449	                return Err(VerifyError::UndisclosedClaim(disclosure.name));
450	            }
451	            claims.insert(disclosure.name, disclosure.value);
452	        }
453	
454	        Ok(VerifiedPresentation { holder: holder.to_string(), credential, claims })
455	    }
456	
457	    /// Verifies a credential: issuer proof, validity window and status.
458	    pub fn verify_credential(&self, vc: &Value) -> Result<VerifiedCredential, VerifyError> {
459	        let issuer = str_field(vc, "issuer")?;
460	        let subject = vc.pointer("/credentialSubject/id").and_then(Value::as_str).ok_or_else(|| malformed("credentialSubject.id"))?;
461	        let id = str_field(vc, "id")?;
462	
463	        let document = self.resolve_issuer(issuer)?;
464	        check_proof(vc, &document, &document.assertion_method)?;
465	
466	        let now = (self.clock)();
467	        let not_before = int_field(vc, "not_before")?;
468	        let expires_at = int_field(vc, "expires_at")?;
469	        if now < not_before {
470	            return Err(VerifyError::NotYetValid);
471	        }
472	        if now > expires_at {
473	            return Err(VerifyError::Expired);
474	        }
475	
476	        let list = vc.pointer("/credentialStatus/statusListId").and_then(Value::as_str).ok_or_else(|| malformed("credentialStatus"))?;
477	        let index = vc.pointer("/credentialStatus/statusListIndex").and_then(Value::as_u64).ok_or_else(|| malformed("credentialStatus"))?;
478	        match self.store.is_revoked(list, index as usize) {
479	            Some(false) => {}
480	            Some(true) => return Err(VerifyError::Revoked),
481	            None => return Err(VerifyError::UnknownStatus(list.to_string())),
482	        }
483	
484	        let issuer_site = document
485	            .service
486	            .iter()
487	            .find(|service| service.type_.iter().any(|t| t == "LinkedDomains"))
488	            .and_then(|service| service.service_endpoint.get_uri());
489	
490	        Ok(VerifiedCredential {
491	            id: id.to_string(),
492	            issuer: issuer.to_string(),
493	            subject: subject.to_string(),
494	            expires_at,
495	            issuer_site,
496	        })
497	    }
498	
499	    /// The DID document an issuer's credentials are checked against.
500	    pub fn resolve_issuer(&self, did: &str) -> Result<Document, VerifyError> {
501	        // Issuer documents are self-contained, as with the peer DIDs issuers
502	        // first onboarded with: keys and service endpoints travel with the
503	        // document, so the copy recorded at onboarding is all verification needs.
504	        if let Some(issuer) = self.store.onboarded_issuer(did) {
505	            return Ok(issuer.document);
506	        }
507	        Ok(self.resolver.resolve(did)?)
508	    }
509	}
510	
511	/// Checks `document`'s proof against a key `signer` lists under `relationship`.
512	fn check_proof(document: &Value, signer: &Document, relationship: &[VerificationRelationship]) -> Result<(), VerifyError> {
513	    let proof = document.get("proof").ok_or_else(|| malformed("proof"))?;
514	    if proof.get("type").and_then(Value::as_str) == Some(ED25519_SIGNATURE_2020) {
515	        let method = proof.get("verificationMethod").and_then(Value::as_str).ok_or_else(|| malformed("proof.verificationMethod"))?;
516	        let key = listed_key(signer, relationship, method)?;
517	        credential::verify_signature(document, &key).map_err(VerifyError::BadSignature)?;
518	    }
519	    Ok(())
520	}
521	
522	fn listed_key(signer: &Document, relationship: &[VerificationRelationship], method: &str) -> Result<VerifyingKey, VerifyError> {
523	    let unknown = || VerifyError::UnknownKey(method.to_string());
524	    let absolute = |reference: &str| match reference.strip_prefix('#') {
525	        Some(fragment) => format!("{}#{fragment}", signer.id),
526	        None => reference.to_string(),
527	    };
528	    let listed = relationship.iter().find_map(|entry| match entry {
529	        VerificationRelationship::Reference(reference) if absolute(reference) == method => {
530	            signer.verification_method.iter().find(|vm| absolute(vm.id.as_str()) == method).cloned()
531	        }
532	        VerificationRelationship::VerificationMethod(vm) if absolute(vm.id.as_str()) == method => Some((**vm).clone()),
533	        _ => None,
534	    });
535	    let vm = listed.ok_or_else(unknown)?;
536	    match vm.decode_public_key() {
537	        Ok((affinidi_encoding::ED25519_PUB, bytes)) => {
538	            let bytes: [u8; 32] = bytes.try_into().map_err(|_| unknown())?;
539	            VerifyingKey::from_bytes(&bytes).map_err(|_| unknown())
540	        }
541	        _ => Err(unknown()),
542	    }
543	}
544	
545	fn malformed(field: &str) -> VerifyError {
546	    VerifyError::Malformed(format!("missing or invalid {field}"))
547	}
548	
549	fn str_field<'a>(value: &'a Value, field: &str) -> Result<&'a str, VerifyError> {
550	    value.get(field).and_then(Value::as_str).ok_or_else(|| malformed(field))
551	}
552	
553	fn int_field(value: &Value, field: &str) -> Result<i64, VerifyError> {
554	    value.get(field).and_then(Value::as_i64).ok_or_else(|| malformed(field))
555	}
556	
557	fn unix_now() -> i64 {
558	    std::time::SystemTime::now()
559	        .duration_since(std::time::UNIX_EPOCH)
560	        .map(|d| d.as_secs() as i64)
561	        .unwrap_or_default()
562	}
